tokens.css:
:root {
  --sky-zenith: #1F64D4;
  --sky-mid: #5E98E4;
  --sky-horizon: #9DCBF4;
  --white-page: #F6FAFF;
  --white-plate: #EAF4FF;
  --white-lit: #DDEDFF;
  --white-shade: #B3CBEA;
  --white-specular: #FFFFFF;
  --acrylic-thin: #B9E0FF;
  --acrylic-body: #2E8BF0;
  --acrylic-edge: #1E6BFF;
  --acrylic-core: #0A43B0;
  --acrylic-caustic: #8FC8FF;
  --cta-body: linear-gradient(180deg, #1457D8 0%, #0A43B0 100%);
  --grass-tip: #A8F03A;
  --grass-body: #3DCB2A;
  --grass-base: #13702A;
  --grass-ink: #06380F;
  --ink: #0A2350;
  --ink-muted: #34507F;
  --on-blue: #FFFFFF;
  --tint-thin: rgba(46,139,240,0.08);
  --tint-medium: rgba(46,139,240,0.16);
  --tint-thick: rgba(46,139,240,0.28);
  --edge-specular: inset 0 1px 0 rgba(255,255,255,0.90);
  --edge-rim: inset 0 -1px 0 rgba(10,67,176,0.45);
  --edge-outline: inset 0 0 0 1px rgba(10,67,176,0.18);
  --edge-border-gradient: linear-gradient(180deg, rgba(255,255,255,0.95), rgba(143,200,255,0.55) 45%, rgba(10,67,176,0.55)) border-box;
  --glow-exit: inset 0 -14px 24px -10px rgba(143,200,255,0.55);
  --glow-ambient: inset 0 0 18px rgba(143,200,255,0.18);
  --shadow-spill: 0 18px 40px -12px rgba(46,139,240,0.40);
  --shadow-spill-hero: 0 40px 80px -24px rgba(30,107,255,0.40);
  --shadow-contact: 0 2px 6px rgba(10,67,176,0.18);
  --caustic-pool: radial-gradient(50% 40% at 50% 50%, rgba(255,255,255,0.90) 0%, rgba(143,200,255,0.60) 35%, rgba(46,139,240,0) 100%);
  --backdrop: blur(14px) saturate(1.4);
  --radius-card: 24px;
  --radius-panel: 32px;
  --radius-pill: 9999px;
  --radius-icon: 16px;
  --gradient-sky: linear-gradient(180deg, #1F64D4 0%, #5E98E4 46%, #9DCBF4 76%, #F6FAFF 86%);
  --face-panel: linear-gradient(180deg, rgba(255,255,255,0.55) 0%, rgba(255,255,255,0) 32%), linear-gradient(180deg, rgba(46,139,240,0.06) 0%, rgba(46,139,240,0.20) 100%), rgba(234,244,255,0.78);
  --face-pill: linear-gradient(180deg, rgba(255,255,255,0.50) 0%, rgba(255,255,255,0.15) 30%, rgba(255,255,255,0) 38%), radial-gradient(70% 30% at 50% 100%, rgba(143,200,255,0.55), rgba(143,200,255,0) 100%), linear-gradient(180deg, #1457D8 0%, #0A43B0 100%);
  --panel-shadow: var(--edge-specular), var(--edge-rim), var(--edge-outline), var(--glow-exit), var(--shadow-spill), var(--shadow-contact);
}
